BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT121-S4-Q17$batch02$ AND q.stimulus=$batch02$A large amount of rainfall in April and May typically leads to an increase in the mosquito population and thus to an increased threat of encephalitis. People cannot change the weather. Thus people cannot decrease the threat of encephalitis.$batch02$ AND q.prompt=$batch02$The reasoning in the argument above is flawed in that the argument$batch02$ AND q.correct_choice=$batch02$C$batch02$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT121-S4-Q17$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT121-S4-Q17$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$People cannot decrease the threat of encephalitis.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Heavy spring rain increases mosquitoes and so increases the threat. People cannot change the weather.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Grant both premises. Rain is one thing that drives the threat, and we cannot control rain. Does that leave us with no way to reduce the threat? What about draining standing water, spraying for mosquitoes, using nets, or a vaccine? The argument treats one uncontrollable cause as if it were the only lever. If the threat depends on other things too, we can push on those.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Find the answer saying the threat depends on more than just the rainfall.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT121-S4-Q17$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The link from rain to mosquitoes to encephalitis is given as a premise ("typically leads to"). The argument does not infer that link from the order of events, so there is no post hoc move to criticize.$batch02$), ($batch02$B$batch02$, $batch02$Nothing in the argument depends on whether a lower threat is desirable. Obviously it is, but the question is whether it is possible.$batch02$), ($batch02$C$batch02$, $batch02$The threat may depend on rainfall *and* on mosquito control, standing water, protection from bites and more. If so, being unable to change the weather does not stop us from lowering the threat through the other factors. One factor we cannot control is not every factor.$batch02$), ($batch02$D$batch02$, $batch02$The argument does not claim encephalitis disappears without heavy rain. Even if the threat existed in dry years too, the author would still conclude that it cannot be reduced. Negate (D) and nothing changes.$batch02$), ($batch02$E$batch02$, $batch02$"People cannot change the weather" is already a premise about what is possible. The argument moves from one claim about possibility to another. The problem is the missing factors, not a jump from actual to possible.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT121-S4-Q17$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
